<?php
require_once dirname(__DIR__,2).'/src/actions.php';require_once dirname(__DIR__,2).'/src/notifications.php';require_method('POST');$u=current_user();$d=request_json();$chat=(string)($d['chat_id']??'');if(!chat_member($chat,$u['id']))json_response(['error'=>['code'=>'forbidden','message'=>'Chat unavailable']],403);
mutate($u,$d,'chat.screenshot',function($pdo)use($u,$chat){$text=$u['display_name'].' took a screenshot';$id=uuid_v4();$q=$pdo->prepare("INSERT INTO messages(id,chat_id,sender_id,body,type,created_at) VALUES(?,?,?,?,'system',UTC_TIMESTAMP(6))");$q->execute([$id,$chat,$u['id'],$text]);$q=$pdo->prepare('SELECT user_low,user_high FROM chats WHERE id=?');$q->execute([$chat]);$c=$q->fetch();notify_user($pdo,$c['user_low']===$u['id']?$c['user_high']:$c['user_low'],$u['id'],'screenshot',$id,$text,['chatId'=>$chat]);return ['id'=>$id,'body'=>$text];});
